    ('G97', 'ปลานิล, ต้ม', 'Nile tilapia, boiled', 'Oreochromis niloticus', 123.0, 21.25, 4.2, 0.05, 0.0, null, 74.0, 190.0, 1.0, 82.0, null),
    ('G98', 'ปลานิล, สด', 'Nile tilapia, raw', 'Oreochromis niloticus', 87.0, 19.36, 1.1, 0.0, 0.0, null, 87.0, 51.0, 0.91, 58.0, null),
    ('G99', 'ปลานิล, ทอด', 'Nile tilapia, fried', 'Oreochromis niloticus', 321.0, 30.63, 21.8, 0.57, 0.0, null, 146.0, 264.0, 2.1, 69.0, null),
    ('J9', 'English name:', 'Milk, cultured, Yakultฎ brand, per 100 mL', null, 82.0, 1.5, 0.09, 18.89, 0.0, null, null, 50.0, 0.35, null, null)
),
inmu_foods as (
  select food_code::text, name_th::text, name_en::text, scientific_name::text,
         kcal::numeric, protein::numeric, fat::numeric, carbs::numeric,
         fiber::numeric, sugar::numeric, sodium::numeric, calcium::numeric,
         iron::numeric, cholesterol::numeric, edible_portion_percent::numeric
  from raw
),
updated as (
  update public.foods_catalog f
  set energy_kcal_per_100g = i.kcal,
      protein_g_per_100g = i.protein,
      fat_g_per_100g = i.fat,
      carbs_g_per_100g = i.carbs,
      fiber_g_per_100g = coalesce(i.fiber, f.fiber_g_per_100g),
      sugar_g_per_100g = coalesce(i.sugar, f.sugar_g_per_100g),
      sodium_mg_per_100g = coalesce(i.sodium, f.sodium_mg_per_100g),
      calcium_mg_per_100g = coalesce(i.calcium, f.calcium_mg_per_100g),
      iron_mg_per_100g = coalesce(i.iron, f.iron_mg_per_100g),
      cholesterol_mg_per_100g = coalesce(i.cholesterol, f.cholesterol_mg_per_100g),
      edible_portion_percent = coalesce(i.edible_portion_percent, f.edible_portion_percent),
      has_sugar_data = coalesce(i.sugar, f.sugar_g_per_100g) is not null,
      has_sodium_data = coalesce(i.sodium, f.sodium_mg_per_100g) is not null,
      is_usable = true,
      data_quality = case when coalesce(i.sugar, f.sugar_g_per_100g) is not null
                           and coalesce(i.sodium, f.sodium_mg_per_100g) is not null
                          then 'complete' else 'partial' end,
      source_name = 'Thai Food Composition Database, Online version 3, August 2025, Institute of Nutrition, Mahidol University',
      source_url = 'https://inmu.mahidol.ac.th/thaifcd/'
  from inmu_foods i
  where f.food_code = i.food_code
    and (f.is_usable = false or f.source_name like '%(FitFast)%')
  returning f.food_code
)
insert into public.foods_catalog
  (food_code, name_th, name_en, scientific_name, energy_kcal_per_100g,
   protein_g_per_100g, fat_g_per_100g, carbs_g_per_100g, fiber_g_per_100g,
   sugar_g_per_100g, sodium_mg_per_100g, calcium_mg_per_100g, iron_mg_per_100g,
   cholesterol_mg_per_100g, edible_portion_percent, serving_basis_grams,
   is_usable, has_sugar_data, has_sodium_data, data_quality, source_name,
   source_url, verified)
select i.food_code, i.name_th, i.name_en, i.scientific_name, i.kcal, i.protein,
       i.fat, i.carbs, i.fiber, i.sugar, i.sodium, i.calcium, i.iron,
       i.cholesterol, i.edible_portion_percent, 100, true, i.sugar is not null,
       i.sodium is not null,
       case when i.sugar is not null and i.sodium is not null
            then 'complete' else 'partial' end,
       'Thai Food Composition Database, Online version 3, August 2025, Institute of Nutrition, Mahidol University', 'https://inmu.mahidol.ac.th/thaifcd/', false
from inmu_foods i
where not exists (
  select 1 from public.foods_catalog f where f.food_code = i.food_code
);

select is_usable, count(*) from public.foods_catalog group by is_usable;
